const id = $json.body.message_id;
const uuidRe = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (typeof id !== 'string' || !uuidRe.test(id)) {
  throw new Error('message_id missing or not a valid UUID: ' + JSON.stringify(id));
}
return [{ json: { message_id: id } }];

const message = $('Get message').item.json;
const rows = $input.all().map(i => i.json).filter(c => c && c.id);
const campaign = (message.campaign_id && rows.find(c => c.id === message.campaign_id)) || rows[0] || null;
return [{ json: campaign || {} }];

const message = $('Get message').item.json;
const client = $('Get client').item.json;
const resolved = $('Resolve campaign').item.json;
const campaign = resolved && resolved.id ? resolved : null;
const metricsRows = $('Get campaign metrics').all().map(i => i.json).filter(m => m && m.id);
const recRows = $('Get open recommendations').all().map(i => i.json).filter(r => r && r.id);

const totals = metricsRows.reduce((acc, m) => {
  acc.spend += Number(m.spend || 0);
  acc.results += Number(m.results || 0);
  acc.roasSum += m.roas != null ? Number(m.roas) : 0;
  acc.roasN += m.roas != null ? 1 : 0;
  return acc;
}, { spend: 0, results: 0, roasSum: 0, roasN: 0 });

const recsText = recRows.length
  ? recRows.map(r => '- ' + (r.type || 'recommendation') + (r.dollars_recoverable != null ? ': $' + r.dollars_recoverable + ' recoverable' : '')).join('\n')
  : 'None currently open.';

return [{ json: {
  businessName: client.business_name || client.name,
  campaignId: campaign ? campaign.id : null,
  campaignName: campaign ? campaign.campaign_name : 'none yet',
  campaignStatus: campaign ? campaign.status : 'n/a',
  dailyBudgetUsd: campaign ? campaign.daily_budget_usd : null,
  totalSpend: totals.spend,
  totalResults: totals.results,
  costPerResult: totals.results > 0 ? totals.spend / totals.results : null,
  roas: totals.roasN > 0 ? totals.roasSum / totals.roasN : null,
  recommendationsText: recsText,
  clientMessage: message.body,
} }];

